const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bi=(en,cn,cls='')=>`<span class="bi ${cls}"><span>${en}</span><small lang="zh-CN">${cn}</small></span>`;
const paths={calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',folder:'<path d="M3 7a3 3 0 0 1 3-3h4l2 3h6a3 3 0 0 1 3 3v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',room:'<path d="M4 21h16M6 21V5a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v16M14 12h.01"/>',contact:'<rect x="4" y="3" width="16" height="18" rx="2"/><circle cx="12" cy="9" r="3"/><path d="M8 17a4 4 0 0 1 8 0"/>',link:'<path d="M10 13a5 5 0 0 0 7 .2l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7-.2l-3 3a5 5 0 0 0 7 7l2-2"/>',left:'<path d="m14 7-5 5 5 5"/>',right:'<path d="m10 7 5 5-5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h3"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6Z M13 6l5 5"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.calendar}</svg>`;
const pages={schedule:['Schedule','排班工作台','Your week, across people, projects and rooms.','按人员、项目和房间查看每周安排。','calendar'],members:['Members','人员目录','The people behind every session.','统一管理主播和场控。','users'],projects:['Projects','项目目录','Keep every project and its weekly schedule together.','集中管理项目及其每周排班。','folder'],rooms:['Rooms','房间目录','One shared directory for every room.','所有项目共用的房间目录。','room'],pms:['Project managers','PM 目录','Projects, organized by their owner.','按负责人整理项目。','contact'],entry:['Availability entry','人员填写入口','One shared link for your entire team.','全员共用一个链接，选择姓名后填写时间。','link']};
const roles={host:['Host','主播'],moderator:['Moderator','场控'],both:['Host & Moderator','主播兼场控']};
const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const part=n=>parts.find(p=>p.type===n).value;const today=`${part('year')}-${part('month')}-${part('day')}`;
let state={week:monday(today),scope:'member',view:'calendar',selected:{member:'',project:'',room:''},mode:'preview',overlays:[],memberRole:'all',zoom:'normal',entryMember:'',dirty:false,availability:null,slots:blank(),loadId:0};
let records={members:[],projects:[],rooms:[]},isAdmin=false,route='schedule',grid=null,savePending=false;
const employee=location.pathname==='/availability';
try{const pref=JSON.parse(sessionStorage.getItem('studio-ui')||'{}');if(/^\d{4}-\d{2}-\d{2}$/.test(pref.week)&&!Number.isNaN(+parseDate(pref.week)))state.week=monday(pref.week);if(['member','project','room'].includes(pref.scope))state.scope=pref.scope;if(['calendar','table'].includes(pref.view))state.view=pref.view}catch{}
if(employee) state.view='calendar';
function remember(){try{sessionStorage.setItem('studio-ui',JSON.stringify({week:state.week,scope:state.scope,view:state.view}))}catch{}}
const errors={admin_required:['Company access required','需要公司端权限'],storage_unavailable:['Unable to load or save. Please try again.','暂时无法读取或保存，请重试。'],duplicate_record:['This record already exists.','此记录已存在。'],availability_changed:['This week was updated elsewhere. Reload before saving.','此周已被其他人更新，请重新载入后再保存。'],invalid_fields:['Please check the required fields.','请检查必填字段。'],member_not_found:['This member is no longer available.','找不到该人员。']};
async function api(path,options={}){const res=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await res.json();if(!res.ok){const e=new Error(data.error||'storage_unavailable');e.code=data.error;e.details=data.details||[];throw e}return data}
function errorHTML(e){const m=errors[e.code||e.message]||errors.storage_unavailable;return bi(...m)}
let toastTimer;function toast(en,cn){$('#toast').innerHTML=icon('check')+bi(en,cn);$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
function notice(e){$('#toast').innerHTML=errorHTML(e);$('#toast').hidden=false;clearTimeout(toastTimer)}
async function confirmAction(en,cn){const d=$('#confirm-dialog');d.innerHTML=`<h2 id="confirm-title">${bi(en,cn)}</h2><div class="dialog-actions"><button class="button" data-answer="no">${bi('Cancel','取消')}</button><button class="button primary" data-answer="yes">${bi('Continue','继续')}</button></div>`;d.showModal();return new Promise(resolve=>{let done=false;const end=v=>{if(done)return;done=true;d.close();resolve(v)};d.querySelector('[data-answer=no]').onclick=()=>end(false);d.querySelector('[data-answer=yes]').onclick=()=>end(true);d.oncancel=e=>{e.preventDefault();end(false)}})}
async function guard(){return !state.dirty||await confirmAction('Discard unsaved changes?','放弃尚未保存的可用时间？')}
function shell(){if(employee){$('#app').innerHTML=`<header class="employee-header"><a class="brand" href="/availability"><span class="brand-mark">${icon('calendar')}</span><span>LiveLab<span class="brand-sub">Schedule workdesk</span></span></a><span class="timezone-badge">${icon('clock')}${bi('Los Angeles time','洛杉矶时间')}</span></header><main id="main" class="employee-main" tabindex="-1"></main>`;return}$('#app').innerHTML=`<div class="app"><aside class="sidebar" id="sidebar"><a class="brand" href="#schedule"><span class="brand-mark">${icon('calendar')}</span><span>LiveLab<span class="brand-sub">Schedule workdesk</span></span></a><div class="workspace">${icon('contact')}${bi('Company workspace','PM / HR 公司工作台')}</div><div class="nav-caption">${bi('WORKSPACE','工作空间')}</div><nav aria-label="Main directory / 主目录">${Object.entries(pages).map(([id,p])=>`<a href="#${id}" data-route="${id}">${icon(p[4])}${bi(p[0],p[1])}</a>`).join('')}</nav><div class="sidebar-foot">${icon('clock')}${bi('Los Angeles','统一使用洛杉矶时间')}</div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-button menu-button" id="menu" aria-label="Open menu / 打开目录">${icon('menu')}</button>${bi('Workspace','工作空间')}<span>/</span><strong id="breadcrumb"></strong></div><a class="entry-shortcut" href="#entry">${icon('link')}${bi('Availability entry','人员填写入口')}</a></header><main id="main" tabindex="-1"></main></div></div><div class="scrim" id="scrim" hidden></div>`;$('#menu').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#scrim').hidden=!open;$('#menu').setAttribute('aria-expanded',String(open))};$('#scrim').onclick=()=>{$('#sidebar').classList.remove('open');$('#scrim').hidden=true}}
function heading(en,cn,desc,zh,action=''){return `<div class="page-heading"><div><h1>${bi(en,cn)}</h1>${desc?`<p>${bi(desc.replace(/[.。]$/,''),zh.replace(/[.。]$/,''))}</p>`:''}</div>${action}</div>`}
function weekBar(){const d=parseDate(state.week),end=parseDate(plus(state.week,6));const f=new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'});return `<section class="week-bar" aria-label="Week selection / 选择周"><div class="week-main"><span class="week-icon">${icon('calendar')}</span><div><span class="week-value">${f.format(d)} – ${f.format(end)} <small>${d.getUTCFullYear()}</small></span><span class="week-cn">${d.getUTCMonth()+1}月${d.getUTCDate()}日 — ${end.getUTCMonth()+1}月${end.getUTCDate()}日 · 周一至周日</span></div></div><div class="week-actions"><span class="timezone-badge">${bi('Los Angeles','洛杉矶')}</span><div class="week-step"><button class="icon-button" data-week="-7" aria-label="Previous week / 上一周">${icon('left')}</button><button data-week="today">${bi('This week','本周')}</button><button class="icon-button" data-week="7" aria-label="Next week / 下一周">${icon('right')}</button></div><label class="date-picker">${bi('Jump to date','选择日期')}<input type="date" value="${state.week}" min="2020-01-01" max="2100-12-31" id="week-date" aria-label="Jump to date / 选择日期"></label></div></section>`}
async function changeWeek(w){if(!await guard()){const date=$('#week-date');if(date)date.value=state.week;return}state.week=w;state.dirty=false;state.availability=null;remember();render()}
function bindWeek(){$$('[data-week]').forEach(b=>b.onclick=()=>changeWeek(b.dataset.week==='today'?monday(today):plus(state.week,Number(b.dataset.week))));const d=$('#week-date');if(d)d.onchange=()=>{if(d.value&&d.validity.valid)changeWeek(monday(d.value));else d.value=state.week}}
function $$(s){return [...document.querySelectorAll(s)]}
function options(list,selected,placeholder){return `<option value="">${placeholder}</option>`+list.map(v=>`<option value="${esc(v.id)}" ${selected===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}
function empty(iconName,en,cn){return `<div class="empty-state"><span class="empty-symbol">${icon(iconName)}</span><h3>${bi(en,cn)}</h3></div>`}
async function baseLoadRecords(){const session=await api('session');isAdmin=session.admin;records.members=(await api('members')).members;if(!employee&&isAdmin){const [p,r]=await Promise.all([api('projects'),api('rooms')]);records.projects=p.projects;records.rooms=r.rooms}}
function viewSwitch(){return `<div class="segment" aria-label="Display view / 展示视角"><button data-view="calendar" aria-pressed="${state.view==='calendar'}">${bi('Calendar','日历')}</button><button data-view="table" aria-pressed="${state.view==='table'}">${bi('Table preview','表格预览')}</button></div>`}
function bindViews(){$$('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;remember();paintScheduleBody()})}
function availabilityMember(){return employee?state.entryMember:state.scope==='member'?state.selected.member:''}
function statusHTML(){if(!state.availability)return bi('Choose a member','请选择人员');if(state.dirty)return bi('Unsaved changes','有尚未保存的修改');if(!state.availability.revision)return bi('Not submitted','本周尚未提交');return bi('Saved · '+new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(state.availability.updatedAt)),'已保存 · 洛杉矶时间')}
function updateDirty(){state.dirty=true;const s=$('#availability-status');if(s)s.innerHTML=statusHTML();const b=$('#save-availability');if(b)b.disabled=false}
function baseSchedule(){const list=state.scope==='member'?records.members:state.scope==='project'?records.projects:records.rooms;return heading('Weekly schedule','每周排班','','')+weekBar()+`<section class="schedule-surface"><div class="schedule-toolbar"><div class="scope-tabs">${[['member','Members','人员'],['project','Projects','项目'],['room','Rooms','房间']].map(([id,en,cn])=>`<button data-scope="${id}" aria-pressed="${state.scope===id}">${bi(en,cn)}</button>`).join('')}</div>${viewSwitch()}</div><div class="schedule-filters"><label class="picker-label">${bi('Select '+state.scope,'选择'+({member:'人员',project:'项目',room:'房间'}[state.scope]))}<select id="entity-select">${options(list,state.selected[state.scope],'Choose / 请选择')}</select></label>${['member','project'].includes(state.scope)?overlayPicker():''}<div class="mode-toggle">${state.scope==='member'?`<button class="button ${state.mode==='availability'?'soft-active':''}" id="toggle-availability" ${!state.selected.member?'disabled':''}>${icon('edit')}${bi(state.mode==='availability'?'Editing availability':'Edit availability',state.mode==='availability'?'正在编辑可用时间':'编辑可用时间')}</button>`:''}</div></div><div id="schedule-body"></div></section>`}
function baseBindSchedule(){$$('[data-scope]').forEach(b=>b.onclick=async()=>{if(!await guard())return;state.scope=b.dataset.scope;state.view='calendar';state.mode='preview';state.dirty=false;state.availability=null;remember();render()});$('#entity-select').onchange=async e=>{const v=e.target.value;if(!await guard()){e.target.value=state.selected[state.scope];return}state.selected[state.scope]=v;state.dirty=false;state.availability=null;render()};bindOverlayPicker();if($('#toggle-availability'))$('#toggle-availability').onclick=async()=>{if(!await guard())return;state.mode=state.mode==='availability'?'preview':'availability';state.dirty=false;state.availability=null;render()};bindViews();paintScheduleBody()}
function rangeForm(){return `<details class="range-details"><summary>${bi('Add a time range','按时间添加，支持键盘或手机操作')}</summary><form id="range-form" class="range-form"><label>${bi('Day','日期')}<select name="day">${['Monday|周一','Tuesday|周二','Wednesday|周三','Thursday|周四','Friday|周五','Saturday|周六','Sunday|周日'].map((d,i)=>`<option value="${i}">${d.replace('|',' / ')}</option>`).join('')}</select></label><label>${bi('From','开始')}<select name="start">${Array.from({length:96},(_,i)=>`<option value="${i}" ${i===36?'selected':''}>${time(i)}</option>`).join('')}</select></label><label>${bi('Until','结束')}<select name="end">${Array.from({length:96},(_,i)=>`<option value="${i+1}" ${i+1===68?'selected':''}>${time(i+1)}</option>`).join('')}</select></label><label>${bi('Mark as','设为')}<select name="fill"><option value="1">Available / 有空</option><option value="0">Unavailable / 没空</option></select></label><button class="button" type="submit">${bi('Apply','应用')}</button><div id="range-error" role="alert"></div></form></details>`}
function availabilityTools(){return `<div class="availability-tools"><div class="availability-hint">${bi('Drag to select. Click or drag again to clear.','拖动框选有空时间，再次点击或拖动可取消。')}<div class="legend"><span><i class="white"></i>${bi('Available','有空')}</span><span><i class="gray"></i>${bi('Unavailable','没空')}</span></div></div><div class="tool-buttons"><button class="button" id="copy-week">${icon('copy')}${bi('Copy last week','复制上周')}</button><button class="button" id="clear-week">${bi('All unavailable','整周没空')}</button></div></div>${rangeForm()}`}
async function basePaintScheduleBody(){grid?.destroy?.();const generation=++state.loadId;const target=employee?$('#entry-calendar-body'):$('#schedule-body');if(!target)return;$$('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===state.view)));const member=availabilityMember(),edit=employee||state.mode==='availability';if(member&&!state.availability){target.innerHTML=`<div class="loading-state">${bi('Loading availability…','正在读取可用时间…')}</div>`;try{const a=await api(`availability?memberId=${encodeURIComponent(member)}&week=${state.week}`);if(generation!==state.loadId)return;state.availability=a;state.slots=clone(a.slots)}catch(e){if(generation!==state.loadId)return;target.innerHTML=`<div class="error-panel">${errorHTML(e)}<button class="button" id="retry-load">${bi('Retry','重试')}</button></div>`;$('#retry-load').onclick=paintScheduleBody;return}}
let banner='';if(!employee&&!state.selected[state.scope])banner=`<div class="inline-note">${bi('Select a '+state.scope+' to view this week.','选择'+({member:'人员',project:'项目',room:'房间'}[state.scope])+'以查看本周安排。')}</div>`;if(!employee&&state.overlays.length&&['member','project'].includes(state.scope))banner+=`<div class="overlay-note">${overlayLegend()}</div>`;
const showAvailability=!!member;target.innerHTML=banner+(!employee&&member&&state.availability?.notes?`<details class="availability-import-notes"><summary>${bi('Availability notes','可用时间备注')}</summary><p>${esc(state.availability.notes)}</p></details>`:'')+(edit&&member?availabilityTools():'')+(state.view==='calendar'?`<div id="week-calendar"></div>`:edit&&member?`<div id="availability-table"></div>`:`<div class="table-scroll"><table><thead><tr>${[['Date','日期'],['Event','活动'],['Time','时间'],['Project','项目'],['Room','房间']].map(x=>`<th>${bi(...x)}</th>`).join('')}</tr></thead><tbody><tr><td colspan="5">${empty('calendar','No events this week','本周暂无活动')}</td></tr></tbody></table></div>`)+(showAvailability?`<div class="save-bar"><span id="availability-status" aria-live="polite">${statusHTML()}</span>${edit?`<div class="save-actions"><button class="button" id="reload-availability">${bi('Reload','重新载入')}</button><button class="button primary" id="save-availability">${icon('check')}${bi('Save this week','保存本周')}</button>${employee?`<button class="button" id="save-next">${bi('Save & next week','保存并填写下一周')}</button>`:''}</div>`:`<div class="legend"><span><i class="white"></i>${bi('Available','有空')}</span><span><i class="gray"></i>${bi('Unavailable','没空')}</span></div>`}</div>`:`<div class="calendar-footer">${bi('24 hours · 15-minute intervals','完整 24 小时 · 每格 15 分钟')}</div>`);
if(state.view==='calendar')grid=calendar($('#week-calendar'),{week:state.week,slots:state.slots,zoom:state.zoom,onZoom:z=>{state.zoom=z},availability:showAvailability,editable:edit&&showAvailability,onChange:s=>{state.slots=s;updateDirty()}});else grid=null;
if(edit&&member){renderAvailabilityTable();bindAvailability()}}
function renderAvailabilityTable(){const target=$('#availability-table');if(!target)return;const rows=intervals(state.slots);target.innerHTML=`<div class="table-download">${employee?excelButton():''}</div><div class="table-scroll"><table><thead><tr><th>${bi('Date','日期')}</th><th>${bi('Available from','开始时间')}</th><th>${bi('Until','结束时间')}</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${plus(state.week,r.day)}</td><td>${time(r.start)}</td><td>${time(r.end)}</td></tr>`).join(''):`<tr><td colspan="3">${empty('clock','No available time selected','尚未选择有空时间')}</td></tr>`}</tbody></table></div>`;bindExcelExport()}
function bindAvailability(){$('#range-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),day=Number(f.get('day')),start=Number(f.get('start')),end=Number(f.get('end'));if(end<=start){$('#range-error').innerHTML=bi('End must be after start. Add overnight time on the next day.','结束须晚于开始；跨日时间请继续填写次日。');return}$('#range-error').textContent='';for(let s=start;s<end;s++)state.slots[day][s]=Number(f.get('fill'));grid?.set(state.slots);renderAvailabilityTable();updateDirty()};$('#clear-week').onclick=async()=>{if(!await confirmAction('Mark the entire week unavailable?','将整周设为没空？保存后生效。'))return;state.slots=blank();grid?.set(state.slots);renderAvailabilityTable();updateDirty()};$('#copy-week').onclick=async()=>{try{if(state.dirty&&!await confirmAction('Replace this draft with last week?','用上周的可用时间替换当前草稿？'))return;const a=await api(`availability?memberId=${encodeURIComponent(availabilityMember())}&week=${plus(state.week,-7)}`);if(!a.revision){toast('Last week has not been submitted','上周尚未填写，未修改当前内容');return}state.slots=clone(a.slots);grid?.set(state.slots);renderAvailabilityTable();updateDirty()}catch(e){notice(e)}};$('#save-availability').onclick=()=>saveAvailability(false);if($('#save-next'))$('#save-next').onclick=()=>saveAvailability(true);$('#reload-availability').onclick=async()=>{if(!await guard())return;state.dirty=false;state.availability=null;paintScheduleBody()}}
async function baseSaveAvailability(next){if(savePending)return;if(!state.availability)return;if(state.availability.revision===0&&!intervals(state.slots).length&&!await confirmAction('Submit this week as unavailable?','确认提交本周全部没空？'))return;savePending=true;const snapshot=clone(state.slots),member=availabilityMember(),week=state.week;$$('.save-actions button').forEach(b=>b.disabled=true);try{const a=await api('availability',{method:'PUT',body:JSON.stringify({memberId:member,week,slots:snapshot,revision:state.availability.revision,source:employee?'member':'admin'})});if(availabilityMember()!==member||state.week!==week)return;state.availability={...a,slots:snapshot};state.dirty=JSON.stringify(snapshot)!==JSON.stringify(state.slots);$('#availability-status').innerHTML=statusHTML();toast('Availability saved','可用时间已保存');if(next&&!state.dirty){state.week=plus(state.week,7);state.availability=null;remember();render()}}catch(e){notice(e)}finally{savePending=false;$$('.save-actions button').forEach(b=>b.disabled=false)}}
function projects(){queueMicrotask(()=>{if(route==='projects')$('#projects-preview').onclick=()=>openSchedule('project','','table')});return heading('Projects','项目目录','Every activity belongs to a project.','直播、Training、拍摄等活动均归属一个项目。',`<div class="row-actions"><button class="button" id="projects-preview">${bi('Weekly table','本周排班表')}</button><button class="button primary" id="new-project">${icon('plus')}${bi('New project','新建项目')}</button></div>`)+`<div class="directory-toolbar"><label class="search-label">${bi('Search projects','搜索项目')}<input id="project-search" type="search" placeholder="Project name / 项目名称"></label><span class="count">${bi(records.projects.length+' projects',records.projects.length+' 个项目')}</span></div><div class="project-grid" id="project-grid"></div>`}
function renderProjectCards(query=''){const list=records.projects.filter(p=>p.name.toLowerCase().includes(query.toLowerCase()));$('#project-grid').innerHTML=list.length?list.map(p=>`<article class="project-card"><div class="project-top"><span class="tile-icon project-color" style="${projectStyle(p.id)}">${icon('folder')}</span><button class="icon-button" data-edit-project="${p.id}" aria-label="Edit project / 编辑项目">${icon('edit')}</button></div><h2>${esc(p.name)}</h2><p class="pm-label">${bi('Project manager','负责人')}<strong>${esc(p.pm)}</strong></p>${p.notes?`<p class="project-notes">${esc(p.notes)}</p>`:''}<div class="project-actions"><button class="button" data-project-calendar="${p.id}">${bi('Open calendar','打开日历')}</button></div></article>`).join(''):`<div class="full-empty">${empty('folder',query?'No matching projects':'Create your first project',query?'没有匹配的项目':'先新建项目，再进入空白周历。')}</div>`;$$('[data-edit-project]').forEach(b=>b.onclick=()=>recordForm('project',records.projects.find(p=>p.id===b.dataset.editProject)));$$('[data-project-calendar]').forEach(b=>b.onclick=()=>openSchedule('project',b.dataset.projectCalendar,'calendar'))}
function baseDirectory(kind){const member=kind==='members',list=member?records.members:records.rooms;return heading(...pages[kind].slice(0,4),`<button class="button primary" id="new-record">${icon('plus')}${bi(member?'New member':'New room',member?'新建人员':'新增房间')}</button>`)+`<div class="directory-table table-scroll"><table><thead><tr>${(member?[['Name','姓名'],['Role','角色'],['Schedule','排班']]:[['Room','房间'],['Schedule','排班']]).map(x=>`<th>${bi(...x)}</th>`).join('')}</tr></thead><tbody>${list.length?list.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td>${member?`<td>${esc(r.companyId)||'—'}</td><td>${bi(...roles[r.role])}</td>`:''}<td><div class="row-actions"><button class="button" data-open-calendar="${r.id}">${bi('Calendar','日历')}</button><button class="button" data-open-table="${r.id}">${bi('Table','表格')}</button></div></td></tr>`).join(''):`<tr><td colspan="4">${empty(member?'users':'room',member?'No members yet':'No rooms yet',member?'由 HR / PM 创建姓名，人员端即可选择填写。':'添加房间后即可查看空白周历。')}</td></tr>`}</tbody></table></div>`}
