function directory(kind){const member=kind==='members';const active=records[kind].filter(r=>!r.archived&&(!member||memberMatches(r))),archived=records[kind].filter(r=>r.archived);const table=(list,old=false)=>`<div class="table-scroll"><table><thead><tr><th>${bi(member?'Member':'Room',member?'人员':'房间')}</th>${member?`<th>${bi('Company ID','公司 ID')}</th><th>${bi('Role','角色')}</th>`:''}<th>${bi('Actions','操作')}</th></tr></thead><tbody>${list.length?list.map(r=>`<tr><td>${esc(r.name)}</td>${member?`<td>${esc(r.companyId)||'—'}</td><td>${bi(...roles[r.role])}</td>`:''}<td><div class="row-actions">${!old?`<button class="button" data-record-edit="${r.id}">${bi('Edit','编辑')}</button><button class="button" data-open-calendar="${r.id}">${bi('Calendar','日历')}</button><button class="button" data-open-table="${r.id}">${bi('Table','表格')}</button>`:''}<button class="button" data-record-archive="${r.id}" data-archived="${old}">${bi(old?'Restore':'Archive',old?'恢复':'归档')}</button></div></td></tr>`).join(''):`<tr><td colspan="${member?4:2}">${empty(member?'users':'room','No records yet','暂无记录，请先新增。')}</td></tr>`}</tbody></table></div>`;queueMicrotask(()=>{if(route!==kind)return;bindMemberRole();$('#directory-preview').onclick=()=>openSchedule(member?'member':'room','','table');$('#directory-excel').onclick=e=>exportDirectoryExcel(kind,e.currentTarget);if(member){$('#import-members').onclick=importMembers;$('#member-template').onclick=()=>downloadCSV([['Name','Company ID','Role'],['Example name','00123','host']],'members-template.csv')}bindRecordActions(kind)});return heading(...pages[kind].slice(0,4),`<div class="row-actions"><button class="button" id="directory-preview">${bi('Weekly table','本周排班表')}</button><button class="button" id="directory-excel">${bi(member?'Schedule · Excel':'Room list · Excel',member?'导出人员排班':'导出房间名单')}</button>${member?`<button class="button" id="member-template">${bi('CSV template','下载模板')}</button><button class="button" id="import-members">${bi('Import members','批量导入')}</button>`:''}<button class="button primary" id="new-record">${icon('plus')}${bi(member?'New member':'New room',member?'新建人员':'新增房间')}</button></div>`)+(member?weekBar():'')+`${member?`<label class="role-filter">${bi('Show members','人员角色筛选')}${memberRoleSelect()}</label>`:''}<section class="directory-table">${member?['host','moderator','both'].map(role=>{const group=active.filter(m=>m.role===role);return group.length?`<div class="member-group-heading">${bi(...roles[role])}<span>${group.length}</span></div>${table(group)}`:''}).join('')||table([]):table(active)}</section>${archived.length?`<details class="archived-records"><summary>${bi('Archived records ('+archived.length+')','已归档记录')}</summary>${table(archived,true)}</details>`:''}`}
function bindRecordActions(kind){$$('[data-record-edit]').forEach(b=>b.onclick=()=>recordForm(kind==='members'?'member':kind==='rooms'?'room':'pm',records[kind].find(r=>r.id===b.dataset.recordEdit)));$$('[data-record-archive]').forEach(b=>b.onclick=async()=>{const archived=b.dataset.archived!=='true';if(archived&&!await confirmAction('Archive this record?','归档后不再出现在新排班选择中，历史记录保留。'))return;try{await api(kind+'/'+b.dataset.recordArchive+'/archive',{method:'PUT',body:JSON.stringify({archived})});await loadRecords();render()}catch(e){notice(e)}})}
function recordForm(kind,existing=null){if(kind==='project'){baseRecordForm(kind,existing);return}if(kind==='member'&&!existing){baseRecordForm(kind);return}const d=$('#record-dialog'),noun=kind==='member'?'member':kind==='room'?'room':'PM',cn=kind==='member'?'人员':kind==='room'?'房间':'PM';d.innerHTML=`<form id="simple-record"><div class="dialog-heading"><h2 id="dialog-title">${bi((existing?'Edit ':'New ')+noun,(existing?'编辑':'新增')+cn)}</h2><button class="icon-button" type="button" id="simple-close" aria-label="Close / 关闭">${icon('close')}</button></div><label>${bi('Name','名称')}<input name="name" required maxlength="100" value="${esc(existing?.name||'')}"></label>${kind==='member'?`<label>${bi('Company ID · optional','公司 ID · 选填')}<input name="companyId" maxlength="100" value="${esc(existing?.companyId||'')}"></label><label>${bi('Role','角色')}<select name="role">${Object.entries(roles).map(([k,v])=>`<option value="${k}" ${existing.role===k?'selected':''}>${v[0]} / ${v[1]}</option>`).join('')}</select></label>`:''}<div id="simple-error" role="alert"></div><div class="dialog-actions"><button class="button primary" type="submit">${bi('Save','保存')}</button></div></form>`;d.showModal();$('#simple-close').onclick=()=>d.close();$('#simple-record').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await api((kind==='member'?'members':kind==='room'?'rooms':'pms')+(existing?'/'+existing.id:''),{method:existing?'PUT':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await loadRecords();d.close();render()}catch(err){$('#simple-error').innerHTML=errorHTML(err);e.submitter.disabled=false}}}
function pmPage(){queueMicrotask(()=>{if(route!=='pms')return;bindPmTransfers();$('#new-pm').onclick=()=>recordForm('pm');$$('[data-pm-create]').forEach(b=>b.onclick=()=>{recordForm('project');$('#record-form').elements.pm.value=b.dataset.pmCreate});$$('[data-pm-delete]').forEach(b=>b.onclick=async()=>{const pm=records.pms.find(p=>p.id===b.dataset.pmDelete);b.closest('details').open=false;const owned=records.projects.filter(p=>!p.archived&&p.pm===pm.name);if(owned.length){toast('Reassign this PM’s projects before deleting','请先将此 PM 的项目转交其他负责人，再删除');return}if(!await confirmAction('Delete '+pm.name+' from the PM directory?','从 PM 目录删除此负责人？'))return;try{await api('pms/'+pm.id+'/archive',{method:'PUT',body:JSON.stringify({archived:true})});await loadRecords();render();toast('PM removed','PM 已删除')}catch(e){notice(e)}})});
const names=[...new Set([...records.pms.filter(p=>!p.archived).map(p=>p.name),...records.projects.filter(p=>!p.archived).map(p=>p.pm)])];return heading(...pages.pms.slice(0,4),`<button class="button primary" id="new-pm">${bi('New PM','新增 PM')}</button>`)+`<p id="pm-drag-help" class="pm-drag-help">${bi('Drag a project to another PM to reassign it','拖动项目到另一位 PM 名下，日历归属会自动同步')}</p><div class="pm-grid">${names.length?names.map(name=>{const pm=records.pms.find(p=>p.name===name);return `<section class="pm-card" data-pm-drop="${esc(name)}"><div class="pm-card-heading"><h2>${esc(name)}</h2>${pm?`<details class="pm-menu dismissible"><summary aria-label="More options for ${esc(name)} / 更多操作">⋯</summary><div class="pm-menu-panel"><button class="danger" data-pm-delete="${pm.id}">${bi('Delete PM','删除 PM')}</button></div></details>`:''}</div><div class="row-actions"><button class="button" data-pm-create="${esc(name)}">${bi('New project','新建项目')}</button></div><div class="pm-drop-label">${bi('Drop a project here','将项目拖到此处')}</div>${records.projects.filter(p=>!p.archived&&p.pm===name).map(p=>`<button class="pm-project" draggable="true" data-project-drag="${p.id}" data-pm-project="${p.id}" title="Drag to another PM / 拖动到其他 PM" aria-describedby="pm-drag-help"><span class="drag-grip" aria-hidden="true">⠿</span><span class="project-chip" style="${projectStyle(p.id)}"><i></i>${esc(p.name)}</span>${bi('Open schedule','查看排班')}</button>`).join('')}</section>`}).join(''):`<div class="full-empty">${empty('contact','Add your first PM','请先新增 PM')}</div>`}</div>`}

function importMembers(){const d=$('#record-dialog');d.innerHTML=`<h2 id="dialog-title">${bi('Import members','批量导入人员')}</h2><p>${bi('Columns: Name, Company ID (optional), Role (host / moderator / both). Up to 500 rows.','列顺序：姓名、公司 ID（选填）、角色（host / moderator / both）。每次最多 500 人。')}</p><input type="file" id="csv-file" accept=".csv,.tsv,text/csv"><label class="notes-label">${bi('Paste CSV or spreadsheet rows','粘贴 CSV 或表格内容')}<textarea id="csv-text" rows="8" placeholder="Name,Company ID,Role"></textarea></label><div id="import-preview"></div><div id="import-error" role="alert"></div><div class="dialog-actions"><button class="button" id="import-close">${bi('Cancel','取消')}</button><button class="button" id="check-import">${bi('Preview','预览')}</button><button class="button primary" id="confirm-import" disabled>${bi('Import','导入')}</button></div>`;d.showModal();let rows=[];$('#import-close').onclick=()=>d.close();$('#csv-file').onchange=async e=>{const f=e.target.files[0];if(f){$('#csv-text').value=await f.text();$('#confirm-import').disabled=true}};$('#csv-text').oninput=()=>$('#confirm-import').disabled=true;$('#check-import').onclick=()=>{try{rows=parseCSV($('#csv-text').value);if(!rows.length||rows.length>500||rows.some(r=>!r.name||!roles[r.role]))throw Error('invalid_csv');$('#import-error').textContent='';$('#import-preview').innerHTML=bi(rows.length+' valid members ready to import',rows.length+' 位人员可导入')+'<ul>'+rows.slice(0,10).map(r=>`<li>${esc(r.name)}${r.companyId?' · '+esc(r.companyId):''} · ${r.role}</li>`).join('')+'</ul>';$('#confirm-import').disabled=false}catch(e){$('#import-error').innerHTML=errorHTML(e);$('#confirm-import').disabled=true}};$('#confirm-import').onclick=async()=>{try{$('#confirm-import').disabled=true;await api('members/import',{method:'POST',body:JSON.stringify({members:rows})});await loadRecords();d.close();render();toast('Members imported','人员已导入')}catch(e){$('#import-error').innerHTML=errorHTML(e);$('#confirm-import').disabled=false}}}
async function boot(){const params=new URLSearchParams(location.hash.slice(1));if(params.has('key')){const key=params.get('key');history.replaceState(null,'',location.pathname);try{await api('admin-access',{method:'POST',body:JSON.stringify({key})})}catch(e){shell();$('#main').innerHTML=`<div class="error-panel">${errorHTML(e)}</div>`;return}}await baseBoot();if(!employee&&!isAdmin&&$('#main'))$('#main').innerHTML=heading('Internal management access','内部管理入口','Open the management link shared by your team.','请使用内部分享的管理链接进入，无需固定邮箱。')+`<a class="button primary" href="/availability">${bi('Open availability entry','进入人员填写页面')}</a>`}
window.addEventListener('focus',()=>{if(!employee&&isAdmin&&route==='schedule'&&!state.dirty&&state.mode==='preview'&&!document.querySelector('dialog[open]')){eventWeek='';state.availability=null;paintScheduleBody()}});
const excelButton=()=>`<button class="button" id="export-excel">${bi('Download Excel','下载 Excel')}</button>`;
const excelDate=ms=>new Date(wall(ms)+'Z');
function exportSelection(){const list=state.scope==='member'?records.members:state.scope==='project'?records.projects:records.rooms;return list.find(x=>x.id===state.selected[state.scope])?.name||'All '+state.scope+'s'}
async function exportCurrentExcel(button){button.disabled=true;try{const availability=employee||state.mode==='availability',member=records.members.find(m=>m.id===availabilityMember());let sheets;const metadata=[['Field / 字段','Value / 内容'],['Week / 周',state.week+' – '+plus(state.week,6)],['Time zone / 时区','America/Los_Angeles'],['View / 视角',availability?'Availability / 可用时间':state.scope],['Selected / 选择',availability?member?.name||'':exportSelection()]];
if(availability){metadata.push(['Status / 状态',state.dirty?'Unsaved draft / 未保存草稿':state.availability?.revision?'Saved / 已保存':'Not submitted / 未提交']);sheets=[{name:'Availability 可用时间',widths:[24,27,27,14],rows:[['Date / 日期','Available from / 开始','Until / 结束','Hours / 小时'],...intervals(state.slots).map(r=>{const start=new Date(plus(state.week,r.day)+'T00:00Z');return [plus(state.week,r.day),new Date(+start+r.start*900000),new Date(+start+r.end*900000),(r.end-r.start)/4]})]}]}else{await ensureEvents();const items=visibleItems(),activityTypes=types;const shifts=role=>e=>e.assignments.filter(a=>a.role===role).map(a=>`${a.member_name} · ${wall(a.start).replace('T',' ')} — ${wall(a.end).replace('T',' ')}`).join('\n');metadata.push(['PM / 负责人',filters.pm||'All / 全部'],['Project filter / 项目筛选',records.projects.find(p=>p.id===filters.project)?.name||'All / 全部']);sheets=[{name:'Schedule 排班',widths:[18,30,22,27,27,12,26,24,42,42,45,24],rowStyles:Object.fromEntries(items.map((x,i)=>[i+1,x.event.cancelled?8:0])),rows:[['Date / 日期','Event / 活动','Type / 类型','Start / 开始','End / 结束','Hours / 小时','Project / 项目','Room / 房间','Host shifts / 主播时段','Moderator shifts / 场控时段','Notes / 备注','Status / 状态'],...items.map(x=>[wall(x.start).slice(0,10),x.event.title,activityTypes[x.event.type].join(' / '),excelDate(x.start),excelDate(x.end),(x.end-x.start)/3600000,x.event.project_name,x.event.room_name,shifts('host')(x.event),shifts('moderator')(x.event),x.event.notes,eventStatus(x.event).join(' / ')])]}]}
sheets.push({name:'Selection 导出范围',rows:metadata,widths:[32,65]});await downloadExcel(sheets,(availability?(member?.name||'Availability'):exportSelection())+'-'+state.week);toast('Export ready','导出完成，请查看文件保存提示')}catch(e){notice(e)}finally{button.disabled=false}}
function bindExcelExport(){const button=$('#export-excel');if(button)button.onclick=()=>exportCurrentExcel(button)}
async function exportDirectoryExcel(kind,button){button.disabled=true;try{if(kind==='members'){const week=state.week,roleFilter=state.memberRole;const [m,e]=await Promise.all([api('members'),api('events?week='+week)]);await downloadExcel(memberScheduleSheets({members:m.members,events:e.events,week,roleFilter}),'Member-schedule-'+week+'-'+roleFilter);toast('Export ready','导出完成，请查看文件保存提示')}else{await downloadExcel([{name:'Rooms 房间',rows:[['Room / 房间'],...records.rooms.filter(r=>!r.archived).map(r=>[r.name])],widths:[35]}],'rooms')}}catch(e){notice(e)}finally{button.disabled=false}}
const publicEntryURL='https://studio-schedule-workspace.nomorepudding.chatgpt.site/availability';
function shareNotice(){return ['localhost','127.0.0.1','::1'].includes(location.hostname)?`<p class="share-pending">${bi('Online entry pending publication. Do not share with staff yet.','正式入口尚未上线，请暂勿发送给员工；本地预览不能跨设备使用。')}</p>`:''}
function employeeShare(){return `<section class="employee-share"><label class="share-link">${bi('Shared availability link','统一时间填写链接')}<input id="employee-share-url" readonly value="${publicEntryURL}"></label><div class="row-actions"><button id="employee-copy-link" class="button">${icon('copy')}${bi('Copy link','复制链接')}</button><button id="employee-qr" class="button">${bi('QR code','二维码')}</button></div>${shareNotice()}</section>`}
function bindEmployeeShare(){const copy=$('#employee-copy-link');if(copy)copy.onclick=()=>copyPublicLink($('#employee-share-url'));const qr=$('#employee-qr');if(qr)qr.onclick=()=>{const d=$('#record-dialog');d.innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${bi('Availability QR code','员工填写二维码')}</h2><button class="icon-button" id="share-close" aria-label="Close / 关闭">${icon('close')}</button></div><div class="share-qr-dialog"><img src="/entry-qr.svg" width="240" height="240" alt="Shared availability QR code / 员工填写二维码"><p>${bi('One shared entry for everyone and every week.','所有员工、所有周使用同一个入口。')}</p>${shareNotice()}<a class="button primary" href="/entry-qr.svg" download="studio-availability-qr.svg">${bi('Download QR code','下载二维码')}</a></div>`;d.showModal();$('#share-close').onclick=()=>d.close()}}
async function copyPublicLink(input){try{await navigator.clipboard.writeText(publicEntryURL);toast('Link copied','链接已复制')}catch{input.select();toast('Select and copy the link','请选中并复制链接')}}

function projectStyle(id){const p=records.projects.find(p=>p.id===id),t=projectTheme(p?.color);return `--event-bg:${t.background};--event-ink:${t.ink};--event-border:${t.border}`}
function overlayLegend(){return records.projects.filter(p=>state.overlays.includes(p.id)).map(p=>`<span class="project-chip" style="${projectStyle(p.id)}"><i></i>${esc(p.name)}</span>`).join('')}
function overlayPicker(){return `<div class="picker-label preview-picker"><span>${bi('Project overlays','项目活动浅色预览 · 可多选')}</span><details class="overlay-picker dismissible"><summary id="overlay-summary">${overlaySummary()}</summary><div class="overlay-menu"><input type="search" id="overlay-search" class="select-search" placeholder="Type a project / 输入项目搜索" aria-label="Search project overlays / 搜索项目预览"><div class="overlay-actions"><button type="button" id="overlay-all">${bi('Select all','全选')}</button><button type="button" id="overlay-none">${bi('Clear','清空')}</button></div>${records.projects.filter(p=>!p.archived).map(p=>`<label class="overlay-option" style="${projectStyle(p.id)}"><input type="checkbox" data-overlay="${p.id}" ${state.overlays.includes(p.id)?'checked':''}><i class="project-dot"></i><span>${esc(p.name)}</span></label>`).join('')||bi('No projects yet','暂无项目')}</div></details></div>`}
function overlaySummary(){return bi(state.overlays.length?state.overlays.length+' projects selected':'Choose projects',state.overlays.length?state.overlays.length+' 个项目已选':'选择预览项目')}
function bindOverlayPicker(){const search=$('#overlay-search');if(search)search.oninput=()=>{$$('.overlay-option').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(search.value.trim().toLowerCase()))};const refresh=()=>{$('#overlay-summary').innerHTML=overlaySummary();paintScheduleBody()};$$('[data-overlay]').forEach(i=>i.onchange=()=>{state.overlays=$$('[data-overlay]:checked').map(x=>x.dataset.overlay);refresh()});if($('#overlay-all'))$('#overlay-all').onclick=()=>{$$('[data-overlay]').forEach(i=>i.checked=true);state.overlays=$$('[data-overlay]').map(i=>i.dataset.overlay);refresh()};if($('#overlay-none'))$('#overlay-none').onclick=()=>{$$('[data-overlay]').forEach(i=>i.checked=false);state.overlays=[];refresh()}}
function scheduleTable(items){const shift=(e,role)=>e.assignments.filter(a=>a.role===role).map(a=>`<div class="table-shift"><strong>${esc(a.member_name)}</strong><small>${wall(a.start).replace('T',' ')} — ${wall(a.end).replace('T',' ')}</small></div>`).join('')||'—';return `<table class="schedule-table"><caption>${bi(items.length+' scheduled rows · '+exportSelection(),items.length+' 条排班 · 洛杉矶时间')}<span>${state.week} — ${plus(state.week,6)}</span></caption><thead><tr>${[['Date / time','日期与时间'],['Event / type','活动及类型'],['Project','项目'],['Room','房间'],['Hours','小时'],['Hosts','主播'],['Moderators','场控'],['Notes','备注']].map(t=>`<th>${bi(...t)}</th>`).join('')}</tr></thead><tbody>${items.length?items.map((x,i)=>`<tr class="${x.event.cancelled?'cancelled-row':''}"><td>${wall(x.start).replace('T',' ')}<br>— ${wall(x.end).replace('T',' ')}</td><td><button class="event-table-link" data-event-row="${i}">${esc(x.event.title)}</button>${x.event.cancelled?`<span class="cancelled-tag">${esc(eventStatus(x.event).join(' / '))}</span>`:''}<small class="table-meta">${bi(...types[x.event.type])}</small></td><td><span class="project-chip" style="${projectStyle(x.event.project_id)}"><i></i>${esc(x.event.project_name)}</span></td><td>${esc(x.event.room_name)}</td><td>${Number(((x.end-x.start)/3600000).toFixed(2))}</td><td>${shift(x.event,'host')}</td><td>${shift(x.event,'moderator')}</td><td class="table-notes">${esc(x.event.notes)||'—'}</td></tr>`).join(''):`<tr><td colspan="8">${empty('calendar','No events this week','本周暂无活动')}</td></tr>`}</tbody></table>`}

function memberMatches(m){return state.memberRole==='all'||m.role===state.memberRole||m.role==='both'}
function memberRoleSelect(){return `<select id="member-role-filter" aria-label="Member role / 人员角色"><option value="all" ${state.memberRole==='all'?'selected':''}>All / 全部</option><option value="host" ${state.memberRole==='host'?'selected':''}>Hosts / 只看主播</option><option value="moderator" ${state.memberRole==='moderator'?'selected':''}>Moderators / 只看场控</option></select>`}
function bindMemberRole(){const select=$('#member-role-filter');if(select)select.onchange=async()=>{if(!await guard()){select.value=state.memberRole;return}state.memberRole=select.value;render()}}

let projectTransferPending=false;
async function transferProject(projectId,targetPm){
 if(projectTransferPending)return;
 const project=records.projects.find(p=>p.id===projectId);if(!project||project.pm===targetPm)return;
 projectTransferPending=true;const surface=$('.pm-grid');surface?.setAttribute('aria-busy','true');
 try{
  // Read current fields before updating ownership, preserving name/notes/color.
  const latest=(await api('projects')).projects.find(p=>p.id===projectId);
  if(!latest||latest.archived)throw Object.assign(new Error(),{code:'project_unavailable'});
  if(latest.pm!==project.pm)throw Object.assign(new Error(),{code:'project_owner_changed'});
  await api('projects/'+projectId,{method:'PUT',body:JSON.stringify({name:latest.name,notes:latest.notes,pm:targetPm})});
  records.projects=records.projects.map(p=>p.id===projectId?{...p,...latest,pm:targetPm}:p);
  events=events.map(e=>e.project_id===projectId?{...e,pm:targetPm}:e);eventWeek='';
  if(!employee)render();toast('Moved to '+targetPm,'项目已转交，日历归属已同步');
 }catch(e){notice(e)}finally{projectTransferPending=false;surface?.removeAttribute('aria-busy')}
}
Object.assign(errors,{project_unavailable:['This project is no longer available. Refresh the page.','项目已不可用，请刷新页面。'],project_owner_changed:['This project’s PM changed elsewhere. Refresh before moving it.','项目归属已被其他人修改，请刷新后再拖动。']});
function bindPmTransfers(){
 const surface=$('.pm-grid');if(!surface)return;let moving=null;
 const clear=()=>{surface.classList.remove('dragging-project');surface.querySelectorAll('.drag-over,.project-dragging').forEach(e=>e.classList.remove('drag-over','project-dragging'))};
 let pointer=null,suppressClick=false;
 surface.addEventListener('pointerdown',e=>{const button=e.target.closest('[data-project-drag]');if(!button||e.button!==0||projectTransferPending)return;e.preventDefault();pointer={id:e.pointerId,button,projectId:button.dataset.projectDrag,x:e.clientX,y:e.clientY,started:false};button.setPointerCapture(e.pointerId)});
 surface.addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId)return;if(!pointer.started&&Math.hypot(e.clientX-pointer.x,e.clientY-pointer.y)<6)return;pointer.started=true;surface.classList.add('dragging-project');pointer.button.classList.add('project-dragging');const card=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-pm-drop]');surface.querySelectorAll('.drag-over').forEach(el=>{if(el!==card)el.classList.remove('drag-over')});card?.classList.add('drag-over')});
 surface.addEventListener('pointerup',e=>{if(!pointer||pointer.id!==e.pointerId)return;const p=pointer;pointer=null;if(p.button.hasPointerCapture(e.pointerId))p.button.releasePointerCapture(e.pointerId);if(p.started){suppressClick=true;setTimeout(()=>suppressClick=false,200);const card=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-pm-drop]');clear();if(card)transferProject(p.projectId,card.dataset.pmDrop)}else clear()});
 surface.addEventListener('pointercancel',()=>{pointer=null;clear()});
 surface.addEventListener('click',e=>{if(suppressClick){e.preventDefault();e.stopImmediatePropagation()}},true);
 surface.addEventListener('dragstart',e=>{const button=e.target.closest('[data-project-drag]');if(!button||projectTransferPending){e.preventDefault();return}moving=button.dataset.projectDrag;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',moving);button.classList.add('project-dragging');surface.classList.add('dragging-project')});
 surface.addEventListener('dragover',e=>{const card=e.target.closest('[data-pm-drop]');if(!moving||!card||projectTransferPending)return;e.preventDefault();e.dataTransfer.dropEffect='move';surface.querySelectorAll('.drag-over').forEach(el=>{if(el!==card)el.classList.remove('drag-over')});card.classList.add('drag-over')});
 surface.addEventListener('dragleave',e=>{const card=e.target.closest('[data-pm-drop]');if(card&&!card.contains(e.relatedTarget))card.classList.remove('drag-over')});
 surface.addEventListener('drop',e=>{const card=e.target.closest('[data-pm-drop]');if(!moving||!card)return;e.preventDefault();const id=moving;moving=null;clear();transferProject(id,card.dataset.pmDrop)});
 surface.addEventListener('dragend',()=>{moving=null;clear()});
}

boot();

